// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }

    function testFuzz_property(address actor, uint256 unlockTime, uint256 amount) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(new Log()));
        amount = bound(amount, 1 ether, 1000 ether);
        vm.warp(1000);
        unlockTime = bound(unlockTime, 0, 999); // strictly in the past

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        // Immediate withdrawal attempt right after the deposit.
        vm.prank(actor);
        c.Collect(amount);

        (, uint256 bal) = c.Acc(actor);
        // Reference: unlockTime is clamped to now, so the immediate Collect
        // must fail and the whole deposit remains. Mutant: raw past unlockTime
        // lets Collect succeed, draining the account to 0.
        assertTrue(bal == amount);
    }
}
